    pass

project_task.solution:
memory = []


def remember(user, key, value):
    for doc in memory:
        if doc["user"] == user and doc["key"] == key:
            doc["value"] = value
            return doc
    doc = {"user": user, "key": key, "value": value}
    memory.append(doc)
    return doc


def recall(user, key):
    for doc in memory:
        if doc["user"] == user and doc["key"] == key:
            return doc["value"]
    return None


def forget(user):
    removed = 0
    for doc in list(memory):
        if doc["user"] == user:
            memory.remove(doc)
            removed += 1
    return removed

